  1	use super::ascii;
  2	
  3	pub struct Inflector;
  4	
  5	impl Inflector {
  6	    pub fn initialize() {}
  7	
  8	    pub fn pluralize<T: AsRef<str>>(input: T) -> String {
  9	        if input.as_ref().is_empty() {
 10	            return String::new();
 11	        }
 12	
 13	        let mut output = String::from(input.as_ref());
 14	        output.push('s');
 15	        output
 16	    }
 17	
 18	    pub fn singularize<T: AsRef<str>>(input: T) -> String {
 19	        input
 20	            .as_ref()
 21	            .strip_suffix('s')
 22	            .unwrap_or(input.as_ref())
 23	            .to_string()
 24	    }
 25	
 26	    pub fn camelize<T: AsRef<str>>(input: T) -> String {
 27	        Self::camelize_with_initial(input.as_ref(), false)
 28	    }
 29	
 30	    pub fn underscore<T: AsRef<str>>(input: T) -> String {
 31	        let mut output = String::with_capacity(input.as_ref().len());
 32	        let mut first = true;
 33	
 34	        for ch in input.as_ref().chars() {
 35	            if ascii::is_upper(ch) {
 36	                if !first {
 37	                    output.push('_');
 38	                }
 39	                output.push(ascii::lower(ch));
 40	            } else {
 41	                output.push(ch);
 42	            }
 43	            first = false;
 44	        }
 45	
 46	        output
 47	    }
 48	
 49	    pub fn classify<T: AsRef<str>>(input: T) -> String {
 50	        Self::camelize_with_initial(input.as_ref(), true)
 51	    }
 52	
 53	    pub fn tableize<T: AsRef<str>>(input: T) -> String {
 54	        Self::pluralize(Self::underscore(input))
 55	    }
 56	
 57	    pub fn humanize<T: AsRef<str>>(input: T) -> String {
 58	        let mut output = String::with_capacity(input.as_ref().len());
 59	        let mut first = true;
 60	
 61	        for ch in input.as_ref().chars() {
 62	            let mapped = if ch == '_' { ' ' } else { ch };
 63	            if first {
 64	                output.push(ascii::upper(mapped));
 65	                first = false;
 66	            } else {
 67	                output.push(mapped);
 68	            }
 69	        }
 70	
 71	        output
 72	    }
 73	
 74	    pub fn titleize<T: AsRef<str>>(input: T) -> String {
 75	        let mut output = String::with_capacity(input.as_ref().len());
 76	        let mut word_start = true;
 77	
 78	        for ch in input.as_ref().chars() {
 79	            let lower = ascii::lower(ch);
 80	            if word_start {
 81	                output.push(ascii::upper(lower));
 82	            } else {
 83	                output.push(lower);
 84	            }
 85	            word_start = ascii::is_space(ch);
 86	        }
 87	
 88	        output
 89	    }
 90	
 91	    pub fn dasherize<T: AsRef<str>>(input: T) -> String {
 92	        input
 93	            .as_ref()
 94	            .chars()
 95	            .map(|ch| if ch == '_' { '-' } else { ch })
 96	            .collect()
 97	    }
 98	
 99	    pub fn parameterize<T: AsRef<str>>(input: T) -> String {
100	        let mut output = String::with_capacity(input.as_ref().len());
101	
102	        for ch in input.as_ref().chars() {
103	            if ascii::is_alnum(ch) {
104	                output.push(ascii::lower(ch));
105	            } else if ch == ' ' {
106	                output.push('-');
107	            }
108	        }
109	
110	        output
111	    }
112	
113	    pub fn upcase<T: AsRef<str>>(input: T) -> String {
114	        input.as_ref().chars().map(ascii::upper).collect()
115	    }
116	
117	    pub fn downcase<T: AsRef<str>>(input: T) -> String {
118	        input.as_ref().chars().map(ascii::lower).collect()
119	    }
120	
121	    pub fn capitalize<T: AsRef<str>>(input: T) -> String {
122	        let mut chars = input.as_ref().chars();
123	        let mut output = String::with_capacity(input.as_ref().len());
124	
125	        if let Some(first) = chars.next() {
126	            output.push(ascii::upper(first));
127	        }
128	
129	        for ch in chars {
130	            output.push(ascii::lower(ch));
131	        }
132	
133	        output
134	    }
135	
136	    fn camelize_with_initial(input: &str, upper_first: bool) -> String {
137	        let mut output = String::with_capacity(input.len());
138	        let mut upper_next = upper_first;
139	
140	        for ch in input.chars() {
141	            if ch == '_' {
142	                upper_next = true;
143	                continue;
144	            }
145	
146	            if upper_next {
147	                output.push(ascii::upper(ch));
148	                upper_next = false;
149	            } else {
150	                output.push(ch);
151	            }
152	        }
153	
154	        output
155	    }
